// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.nio.file.Path;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.backup.BackupRequest;
import org.eclipse.rdf4j.sail.backup.BackupType;
import org.eclipse.rdf4j.sail.backup.PointInTimeRestoreRequest;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

@Timeout(30)
class LmdbBackupJournalOwnershipTest {

	@Test
	void anotherRecoveryServiceBorrowsTheLiveJournalWithoutClosingItsOwner(@TempDir Path directory) throws Exception {
		LmdbStore source = new LmdbStore(directory.resolve("source").toFile(),
				new LmdbStoreConfig().setBackupJournalEnabled(true));
		LmdbStore recovery = new LmdbStore(directory.resolve("recovery").toFile(), new LmdbStoreConfig());
		source.init();
		recovery.init();
		try {
			Path backups = directory.resolve("backups");
			LmdbBackupServiceImpl writer = (LmdbBackupServiceImpl) source.getBackupService();
			LmdbBackupServiceImpl reader = (LmdbBackupServiceImpl) recovery.getBackupService();
			var full = writer.createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
			add(source, "first");
			var first = writer.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
					.sinceTransactionId(full.getEndTransactionId())
					.build());
			var generation = source.getBackingStore().backupJournalState().generation();
			Object owner = writer.nativeJournalIdentityForTest(backups, generation);
			assertNotNull(owner);
			assertSame(owner, reader.nativeJournalIdentityForTest(backups, generation),
					"Recovery must share the existing native environment for a live archive");
			assertSame(owner, reader.nativeJournalIdentityForTest(backups.resolve("."), generation),
					"Canonical aliases must refer to the same native environment");
			Path restored = reader.restore(new PointInTimeRestoreRequest(backups, directory.resolve("restored"),
					first.getEndTransactionId(), true));
			assertSize(restored, 1);
			recovery.shutDown();

			add(source, "second");
			var second = writer.createBackup(BackupRequest.builder(backups, BackupType.INCREMENTAL)
					.sinceTransactionId(full.getEndTransactionId())
					.build());
			assertEquals(first.getEndTransactionId() + 1, second.getEndTransactionId());
			assertSame(owner, writer.nativeJournalIdentityForTest(backups, generation),
					"Closing a borrowing service must leave the publisher's native environment alive");
			assertSize(writer.restore(new PointInTimeRestoreRequest(backups, directory.resolve("restored-again"),
					second.getEndTransactionId(), true)), 2);
		} finally {
			recovery.shutDown();
			source.shutDown();
		}
	}

	private static void add(LmdbStore store, String label) {
		var vf = SimpleValueFactory.getInstance();
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(vf.createIRI("urn:journal-owner:" + label), vf.createIRI("urn:journal-owner:p"),
					vf.createLiteral(label));
			connection.commit();
		}
	}

	private static void assertSize(Path directory, long expected) {
		LmdbStore copy = new LmdbStore(directory.toFile(), new LmdbStoreConfig());
		copy.init();
		try (var connection = copy.getConnection()) {
			assertEquals(expected, connection.size());
		} finally {
			copy.shutDown();
		}
	}
}
